package org.eclipse.kura.core.keystore.crl.test;

import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.security.cert.X509CRL;
import java.util.Optional;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.kura.core.testutil.http.TestServer;
import org.eclipse.kura.core.testutil.pki.TestCA;

public class CrlDistributionServer implements Closeable {

    private static final AtomicInteger NEXT_PORT = new AtomicInteger(8285);

    private final int port = NEXT_PORT.getAndIncrement();
    private final BlockingQueue<String> downloads = new LinkedBlockingQueue<>();
    private final TestServer server;

    public CrlDistributionServer() throws Exception {
        this.server = new TestServer(this.port, Optional.of(this.downloads::add));
    }

    public String url(final String path) {
        return "http://localhost:" + this.port + path;
    }

    public void publish(final String path, final X509CRL crl) throws IOException {
        try (final ByteArrayOutputStream out = new ByteArrayOutputStream()) {
            TestCA.encodeToPEM(crl, out);
            this.server.setResource(path, out.toByteArray());
        }
        this.downloads.clear();
    }

    public void awaitDownloads(final String path, final int count, final long timeoutMs)
            throws InterruptedException, TimeoutException {
        final long deadline = System.currentTimeMillis() + timeoutMs;
        int seen = 0;

        while (seen < count) {
            final String download = this.downloads.poll(Math.max(0, deadline - System.currentTimeMillis()),
                    TimeUnit.MILLISECONDS);

            if (download == null) {
                throw new TimeoutException("only " + seen + " downloads of " + path + " within " + timeoutMs + " ms");
            }
            if (download.equals(path)) {
                seen++;
            }
        }
    }

    @Override
    public void close() throws IOException {
        this.server.close();
    }
}
